void sequence_curve_tests(const std::filesystem::path& dir){
    const SequenceController pb{3,0,0},expression{4,11,0},rpn{7,0,0x7f7f},poly{6,0,0};
    require(sequence_curve_minimum(pb)==-8192&&sequence_curve_maximum(pb)==8191&&sequence_curve_minimum(expression)==0&&sequence_curve_maximum(expression)==127,"Pitch bend is signed around zero; Expression retains its7-bit controller domain");
    require(sequence_curve_maximum(rpn)==16383&&sequence_curve_maximum(poly)==127,"RPN values use14bits and PolyAT keeps its per-key7-bit value");
    auto d=SegmentDocument::create_empty({},L"Curves");d.add_tracks({SegmentTrackKind::sequence});d.load(d.save_bytes());const auto original=d.save_bytes();
    SequenceCurve bend;bend.time=192;bend.duration=768;bend.channel=16;bend.start=-8192;bend.end=8191;bend.reset=0;bend.controller=pb;bend.shape=4;bend.flags=1;bend.resetDuration=384;bend.merge=77;
    size_t index=99;require(d.add_curve(bend,&index)&&index==0&&d.notes().empty()&&d.curves().size()==1,"Curve insertion targets existing Sequence without inventing Note events");
    const auto inserted=d.save_bytes();require(d.undo()&&d.save_bytes()==original&&!d.can_undo()&&d.redo()&&d.save_bytes()==inserted,"One Curve insert is one native owner Undo/Redo transaction");
    auto root=Chunk::parse(inserted);Chunk* seq=nullptr;for(auto& track:root.find("LIST","trkl")->children)if(is_sequence_track(track))seq=track.find("seqt");
    const auto evtlBytes=Bytes(seq->data.begin(),seq->data.begin()+12);const auto& bytes=seq->data;
    require(std::string(bytes.begin()+12,bytes.begin()+16)=="curl"&&read32(bytes,20)==32&&read32(bytes,24)==192&&read32(bytes,28)==768&&read32(bytes,32)==384&&read32(bytes,36)==16,"Independent byte offsets audit32-byte DMUS_IO_CURVE_ITEM header/time/duration/reset/PChannel");
    require(bytes[42]==0&&bytes[43]==0&&bytes[44]==0xff&&bytes[45]==0x3f&&bytes[48]==3&&bytes[49]==4&&bytes[50]==0&&bytes[51]==1&&bytes[54]==77&&bytes[46]==0&&bytes[47]==0x20,"Independent native audit checks native14-bit PB extremes shape reset flags and additive ID without7-bit flattening");
    // Signed offset and an unknown DWORD extension must survive edit and reorder.
    put32(seq->data,16,40);put32(seq->data,20,36);seq->data.insert(seq->data.end(),{0xde,0xad,0xbe,0xef});seq->data[40]=0xf9;seq->data[41]=0xff;put32(seq->data,24,199);
    Chunk opaque;opaque.id="zzzz";opaque.data={1,3,5};opaque.padding=0x97;const auto opaqueBytes=opaque.encode();seq->data.insert(seq->data.end(),opaqueBytes.begin(),opaqueBytes.end());d.load(root.encode());
    require(d.curves()[0].time==192&&d.curves()[0].merge==77,"Loaded signed minus7tick offset contributes to effective Curve time");
    auto edit=d.curves()[0];edit.time=384;edit.start=-4096;const auto before=d.save_bytes();require(d.edit_curve(0,edit,&index)&&index==0,"Changing a curve accepts an effective time while preserving its signed offset");
    auto changed=Chunk::parse(d.save_bytes());const Chunk* after=nullptr;for(const auto& track:changed.find("LIST","trkl")->children)if(is_sequence_track(track))after=track.find("seqt");
    require(read32(after->data,24)==391&&after->data[40]==0xf9&&after->data[41]==0xff&&Bytes(after->data.begin()+56,after->data.begin()+60)==Bytes({0xde,0xad,0xbe,0xef}),"Curve change retains signed offset and opaque extended record bytes");
    require(Bytes(after->data.begin(),after->data.begin()+12)==evtlBytes&&Bytes(after->data.end()-opaqueBytes.size(),after->data.end())==opaqueBytes,"Curve authoring preserves complete note payload and opaque subchunk pad");
    require(d.undo()&&d.save_bytes()==before&&!d.dirty()&&d.can_redo(),"Curve edit restores its clean byte checkpoint and retained Redo");
    const auto stable=d.save_bytes();auto invalid=edit;index=88;invalid.start=-8193;require(!d.edit_curve(0,invalid,&index),"PBend below signed lower bound is rejected");invalid=edit;invalid.end=8192;require(!d.add_curve(invalid),"PBend above signed upper bound is rejected");
    for(std::uint32_t channel=0xfffffffcu;;++channel){invalid=edit;invalid.channel=channel;require(!d.add_curve(invalid),"Curve authoring rejects each reserved broadcast PChannel");if(channel==0xffffffffu)break;}
    invalid=edit;invalid.time=d.length()-1;invalid.duration=2;require(!d.edit_curve(0,invalid),"Curve duration cannot extend beyond Segment endpoint");invalid=edit;invalid.controller=expression;invalid.start=0;invalid.end=128;require(!d.add_curve(invalid),"Expression128 is rejected independently of Pitch Bend range");
    invalid=edit;invalid.controller={7,0,0x8080};require(!d.add_curve(invalid),"RPN parameter outside14-bit range is rejected");
    require(d.save_bytes()==stable&&!d.dirty()&&d.can_redo()&&index==88,"Invalid curve edits retain native bytes dirty Undo/Redo and result index");
    require(!d.edit_curve(0,d.curves()[0])&&d.can_redo(),"Unchanged curve edit does not clear Redo");
    SequenceCurve cc;cc.time=96;cc.duration=768;cc.channel=0xfffffffbu;cc.start=127;cc.end=0;cc.reset=127;cc.controller=expression;
    require(d.add_curve(cc,&index)&&index==0&&d.curves()[1].channel==16&&d.curves()[1].time==192,"High DWORD Curve channel and distinct controller sort independently without16-channel limitation");
    auto part=sequence_part_info(d,0);require(part.channels==std::vector<std::uint32_t>({16,0xfffffffbu}),"Curve-only channels appear as distinct Sequence parts");
    cc.controller=rpn;cc.channel=9;cc.time=1536;cc.start=0;cc.end=16383;cc.reset=8192;require(d.add_curve(cc,&index)&&d.curves()[index].controller.parameter==0x7f7f,"RPN parameter and full14-bit values round-trip without CC-number conversion");
    const auto rpnRoot=Chunk::parse(d.save_bytes());const Chunk* rpnPayload=nullptr;for(const auto& track:rpnRoot.find("LIST","trkl")->children)if(is_sequence_track(track))rpnPayload=track.find("seqt");require(rpnPayload->data[rpnPayload->data.size()-opaqueBytes.size()-8]==0x7f&&rpnPayload->data[rpnPayload->data.size()-opaqueBytes.size()-7]==0x7f,"RPN parameter16383 is independently stored as MSB7f/LSB7f rather than packed3fff");
    const auto three=d.save_bytes();require(d.delete_curve(1)&&d.curves().size()==2&&d.curves()[0].controller==expression&&d.undo()&&d.save_bytes()==three,"Deleting one PB curve preserves other controller types and undoes once");
    d.select_track_group(2);d.add_tracks({SegmentTrackKind::sequence});cc.controller=poly;cc.start=2;cc.end=127;cc.reset=0;cc.channel=0;require(d.add_curve(cc)&&d.curves().size()==1,"Curve authoring selects group2 independently");
    d.select_track_group(1);require(d.curves().size()==3&&d.curves()[0].channel==0xfffffffbu,"Group2 edit cannot alias group1 physical Sequence");
    const auto file=dir/L"SequenceCurves.sgp";d.save(file.wstring());SegmentDocument reload;reload.load(read_file(file.wstring()));require(reload.save_bytes()==d.save_bytes()&&!reload.dirty()&&!reload.can_undo()&&reload.curves().size()==3,"Native Curve signed values identities flags and extensions survive independent clean load");
    const auto raw=sequence_track().find("seqt")->data;auto payload=sequence_insert_curve(raw,bend);Bytes duplicate(payload.begin()+12,payload.end());payload.insert(payload.end(),duplicate.begin(),duplicate.end());rejected([&]{sequence_curves(payload);},"Duplicate curl payload is rejected rather than guessing a controller list");
    auto instant=cc;instant.controller=expression;instant.start=127;instant.end=40;instant.reset=127;instant.duration=0;instant.shape=1;const auto instantPayload=sequence_insert_curve(raw,instant);require(sequence_curves(instantPayload)[0].duration==0&&valid_sequence_curve(sequence_curves(instantPayload)[0]),"Imported instantaneous CC with zero duration remains visible and editable");
    auto malformed=raw;put32(malformed,20,30);rejected([&]{sequence_curves(malformed);},"Malformed Curve stride rejects typed reads");
    auto legacy=sequence_insert_curve(raw,bend);put32(legacy,16,32);put32(legacy,20,28);legacy.erase(legacy.begin()+52,legacy.end());const auto old=sequence_curves(legacy);require(old.size()==1&&old[0].merge==0&&old[0].start==-8192,"Legacy28-byte Curve remains readable with zero absent DX8 fields");
    auto legacyChange=old[0];legacyChange.end=0;const auto legacyOut=sequence_change_curve(legacy,0,legacyChange);require(read32(legacyOut,20)==28&&legacyOut.size()==legacy.size()&&sequence_curves(legacyOut)[0].end==0,"Editing legacy Curve does not silently extend its stride");
    legacyChange.controller=rpn;rejected([&]{sequence_change_curve(legacy,0,legacyChange);},"Legacy curve refuses unrepresentable DX8 parameter without corrupting stored records");
    // Empty lanes are document edits, never dummy runtime curves. Preserve the
    // complete unknown legacy design tree and all unrelated track bytes.
    auto lanes=SegmentDocument::create_empty({},L"Empty lanes");lanes.add_tracks({SegmentTrackKind::sequence,SegmentTrackKind::band});lanes.add_note({0,768,0,60,96});lanes.load(lanes.save_bytes());
    const auto laneInitial=lanes.save_bytes();require(lanes.cc_lanes(0).empty()&&lanes.add_cc_lane(0,pb)&&lanes.dirty()&&lanes.can_undo(),"Empty PB lane is a document edit and one Undo transaction");
    const auto oneLane=lanes.save_bytes();require(lanes.curves().empty()&&lanes.notes().size()==1&&lanes.cc_lanes(0)==std::vector<SequenceController>{pb},"Empty lane creates no playback curve or note");
    require(lanes.undo()&&lanes.save_bytes()==laneInitial&&!lanes.dirty()&&lanes.cc_lanes(0).empty()&&lanes.can_redo(),"Undo removes empty lane and restores clean checkpoint");
    require(!lanes.add_cc_lane(1,expression)&&!lanes.add_cc_lane(0,{7,0,0x8080})&&lanes.save_bytes()==laneInitial&&!lanes.dirty()&&lanes.can_redo(),"Absent part and invalid controller retain bytes dirty and Redo");
    require(lanes.redo()&&lanes.save_bytes()==oneLane&&lanes.add_cc_lane(0,expression),"Redo restores empty lane and distinct Expression adds independently");
    const auto twoLanes=lanes.save_bytes();require(lanes.undo()&&lanes.cc_lanes(0)==std::vector<SequenceController>{pb}&&!lanes.add_cc_lane(0,pb)&&lanes.can_redo()&&lanes.redo()&&lanes.save_bytes()==twoLanes,"Duplicate empty lane is a no-op that retains Redo");
    auto initialTree=Chunk::parse(laneInitial),laneTree=Chunk::parse(twoLanes);const auto& initialTracks=initialTree.find("LIST","trkl")->children;const auto& laneTracks=laneTree.find("LIST","trkl")->children;
    for(size_t i=0;i<initialTracks.size();++i){if(is_sequence_track(initialTracks[i]))require(initialTracks[i].find("seqt")->encode()==laneTracks[i].find("seqt")->encode(),"Empty lanes leave complete runtime note and curve payload unchanged");else require(initialTracks[i].encode()==laneTracks[i].encode(),"Empty lanes leave unrelated physical tracks byte-identical");}
    const auto laneFile=dir/L"EmptyCcLanes.sgp";lanes.save(laneFile.wstring());SegmentDocument laneReload;laneReload.load(read_file(laneFile.wstring()));require(laneReload.cc_lanes(0)==std::vector<SequenceController>({pb,expression})&&!laneReload.dirty()&&!laneReload.can_undo(),"Separate clean native load restores two empty CC lanes");
    const auto highPart=laneReload;size_t highIndex=0;require(laneReload.add_sequence_part(0xfffffffbu,&highIndex),"Prepare largest permitted DWORD empty part for lane authoring");laneReload.select_track_group(1,0,0,highIndex);require(laneReload.add_cc_lane(0xfffffffbu,rpn)&&laneReload.cc_lanes(0xfffffffbu)==std::vector<SequenceController>{rpn},"Empty lanes retain largest DWORD PChannel and two seven-bit RPN bytes");
    require(laneReload.undo()&&laneReload.can_redo(),"Prepare redo checkpoint for reserved empty lane channels");const auto invalidLaneBytes=laneReload.save_bytes();const auto invalidLaneDirty=laneReload.dirty();
    for(std::uint32_t c=0xfffffffcu;;++c){require(!laneReload.add_cc_lane(c,pb)&&laneReload.save_bytes()==invalidLaneBytes&&laneReload.dirty()==invalidLaneDirty&&laneReload.can_redo(),"Each reserved empty lane channel leaves document and history intact");if(c==0xffffffffu)break;}
    laneReload.select_track_group(1,0,0,0);require(laneReload.cc_lanes(0)==std::vector<SequenceController>({pb,expression}),"Empty lane edit in another physical part leaves first part unchanged");
    auto badLanes=Chunk::parse(twoLanes);Chunk* laneTrack=nullptr;for(auto& t:badLanes.find("LIST","trkl")->children)if(is_sequence_track(t))laneTrack=&t;
    auto& design=laneTrack->find("qCCL")->data;require(design.size()==40&&read32(design,16)==1&&read32(design,20)==2&&read32(design,24)==0&&design[28]==3&&design[36]==4&&design[37]==11,"Independent owned design byte audit checks version count DWORD channel and distinct controller codes");
    design[16]=2;lanes.load(badLanes.encode());const auto badLaneBytes=lanes.save_bytes();rejected([&]{lanes.add_cc_lane(0,{4,1,0});},"Unknown owned CC design version rejects atomically");require(lanes.save_bytes()==badLaneBytes&&!lanes.dirty()&&!lanes.can_undo(),"Unknown owned version preserves complete document and clean history");
    design[16]=1;put32(design,20,3);lanes.load(badLanes.encode());rejected([&]{lanes.cc_lanes(0);},"Owned lane count mismatch rejects rather than guessing records");
    put32(design,20,2);std::copy(design.begin()+24,design.begin()+32,design.begin()+32);lanes.load(badLanes.encode());rejected([&]{lanes.add_cc_lane(0,{4,1,0});},"Duplicate owned lane records reject before publication");
    auto legacyLanes=Chunk::parse(laneInitial);Chunk* legacyTrack=nullptr;for(auto& t:legacyLanes.find("LIST","trkl")->children)if(is_sequence_track(t))legacyTrack=&t;
    Chunk legacyUi;legacyUi.id="LIST";legacyUi.type="psql";Chunk psqc;psqc.id="psqc";psqc.data.resize(56,0xa7);Chunk cvsu;cvsu.id="cvsu";cvsu.data.resize(8);put32(cvsu.data,0,80);put32(cvsu.data,4,128);legacyUi.children={psqc,cvsu};put32(cvsu.data,4,11);legacyUi.children.push_back(cvsu);Chunk unknown;unknown.id="odd!";unknown.data={1,2,3};unknown.padding=0xb6;legacyUi.children.push_back(unknown);legacyTrack->children.push_back(legacyUi);
    const auto originalUi=legacyUi.encode();lanes.load(legacyLanes.encode());require(lanes.cc_lanes(0)==std::vector<SequenceController>({pb,expression})&&lanes.add_cc_lane(0,{4,1,0}),"Observed channel0 legacy PB128 and Expression11 lanes import alongside new owned lane");
    auto preserved=Chunk::parse(lanes.save_bytes());const Chunk* preservedUi=nullptr;for(const auto& t:preserved.find("LIST","trkl")->children)if(is_sequence_track(t))preservedUi=t.find("LIST","psql");require(preservedUi&&preservedUi->encode()==originalUi,"Legacy psqc unknown fields cvsu and odd padding remain byte-identical after editing");
    legacyTrack->find("LIST","psql")->find("psqc")->data.resize(55);lanes.load(legacyLanes.encode());require(lanes.cc_lanes(0).empty(),"Unobserved psqc layout remains opaque and is not mapped to lanes");
}
